class DynamicHeightCache:
    def __init__(self):
        self.heights = {} # id -> height

    def set_height(self, msg_id: str, height: int):
        self.heights[msg_id] = height

    def compute_offset(self, msg_ids: list, target_id: str) -> int:
        offset = 0
