    def lookup(self, query_vec: list):
        for vec, resp in self.entries:
            if cosine_similarity(query_vec, vec) >= self.threshold:
                return resp
        return None

    def insert(self, query_vec: list, response: str):
        self.entries.append((query_vec, response))

