        self.n = total_nodes
        self.r = read_quorum
        self.w = write_quorum
        self.storage = {i: {} for i in range(total_nodes)}

    def is_strongly_consistent(self) -> bool:
        return (self.r + self.w) > self.n

    def write(self, key: str, value: str, live_nodes: set) -> bool:
        if len(live_nodes) < self.w:
