        reconciled = {}
        for part in cluster_partitions:
            for k, (v, term) in part.items():
                if k not in reconciled or term > reconciled[k][1]:
                    reconciled[k] = (v, term)
        return {k: v for k, (v, _) in reconciled.items()}

