    def cosine_similarity(v1: list, v2: list) -> float:
        norm1 = VectorMetrics.l2_norm(v1)
        norm2 = VectorMetrics.l2_norm(v2)
        if norm1 == 0.0 or norm2 == 0.0: return 0.0
        return VectorMetrics.dot_product(v1, v2) / (norm1 * norm2)

