        self.lower = list(reversed(lower_layers)) # stack of dicts
        self.upper = {} # CoW layer
        self.whiteouts = set()

    def read_file(self, path: str) -> str:
        if path in self.whiteouts:
            raise FileNotFoundError("File deleted")
        if path in self.upper:
